function validateDiscount(discountPercent) {
  if (discountPercent === undefined) return ok(0);
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }
  return ok(discountPercent);
}

function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') return addDays(issueDate, 14);
  if (terms === 'NET30') return addDays(issueDate, 30);
  if (terms === 'EOM') return lastDayOfMonth(issueDate);
  return null;
}

export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

export function discountAmount(line) {
  const discount = line.discountPercent ?? 0;
  return Math.round(lineTotal(line) * discount / 100);
}

export function lineVAT(line) {
  const discountedAmount = lineTotal(line) - discountAmount(line);
  return Math.round(discountedAmount * line.vatRate / 100);
}

export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + discountAmount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
