test('applyVoucher adds voucher to draft invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.voucher.code, 'WELCOME20');
  assert.equal(r2.value.voucher.amount, 2000);
});

test('applyVoucher rejects non-draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const issued = issueInvoice(invoice, []).value;
  const r2 = applyVoucher(issued, { code: 'WELCOME20', amount: 2000 });
  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'NOT_DRAFT');
});

test('applyVoucher rejects non-integer amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000.5 });
  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects zero amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 0 });
  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects negative amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: -1000 });
  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects when voucher already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'FIRST', amount: 1000 });
  assert.equal(r2.ok, true);
  const vouched = r2.value;
  const r3 = applyVoucher(vouched, { code: 'SECOND', amount: 500 });
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'VOUCHER_EXISTS');
});

test('invoiceTotals includes voucher field', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals subtracts voucher from total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  const vouched = r2.value;
  const totals = invoiceTotals(vouched);
  const totalsWithout = invoiceTotals(invoice);
  assert.equal(totals.voucher, 2000);
  assert.equal(totals.total, totalsWithout.total - 2000);
});

test('invoiceTotals clamps total to zero when voucher exceeds amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const totalsWithout = invoiceTotals(invoice);
  const r2 = applyVoucher(invoice, { code: 'BIGDISCOUNT', amount: totalsWithout.total + 5000 });
  const vouched = r2.value;
  const totals = invoiceTotals(vouched);
  assert.equal(totals.total, 0);
});

test('addLine preserves voucher', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  const vouched = r2.value;
  const r3 = addLine(vouched, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r3.value.voucher.code, 'WELCOME20');
  assert.equal(r3.value.voucher.amount, 2000);
});

test('removeLine preserves voucher', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  const vouched = r2.value;
  const r3 = removeLine(vouched, 'DEV-HOUR');
  assert.equal(r3.value.voucher.code, 'WELCOME20');
  assert.equal(r3.value.voucher.amount, 2000);
});

test('issueInvoice preserves voucher', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  const vouched = r2.value;
  const r3 = issueInvoice(vouched, []);
  assert.equal(r3.value.voucher.code, 'WELCOME20');
  assert.equal(r3.value.voucher.amount, 2000);
});

test('applyVoucher does not mutate original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const original = JSON.stringify(invoice);
  applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  assert.equal(JSON.stringify(invoice), original);
});

test('voucher reduces balance due in payments', () => {
  const { recordPayment } = require('../src/payments.js');
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  const vouched = r2.value;
  const issued = issueInvoice(vouched, []).value;
  const totals = invoiceTotals(issued);
  const r3 = recordPayment(issued, { amount: totals.total, date: '2025-10-08' });
  assert.equal(r3.ok, true);
  assert.equal(r3.value.status, 'paid');
});

