test('invoiceTotals with single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // 10 * 9500 = 95000, C-001 is gold tier (5% discount = 4750)
  // Discounted = 90250, VAT 21% = 18953
  // Total = 95000 - 4750 + 18953 = 109203
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18953);
  assert.equal(totals.total, 109203);
});

test('invoiceTotals with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // 10 * 9500 + 1 * 120000 + 5 * 980 = 95000 + 120000 + 4900 = 219900
  // C-001 is gold tier, all lines get 5% discount
  // DEV-HOUR: 90250 * 21% = 18953
  // LOGO-PACK: 114000 * 21% = 23940
  // ICON-SET: 4655 * 21% = 978 (rounded)
  // discount = 10995, vat = 43871, total = 252776
  assert.equal(totals.subtotal, 219900);
  assert.equal(totals.discount, 10995);
  assert.equal(totals.vat, 43871);
  assert.equal(totals.total, 252776);
});

