      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'PRINT-A3', qty: 50 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // 100 * 37 + 50 * 249 = 3700 + 12450 = 16150
  // C-002 is standard tier, no discount
  // PRINT-A4: 3700 * 9% = 333
  // PRINT-A3: 12450 * 9% = 1121 (rounded)
  // VAT = 1454, Total = 17604
  assert.equal(totals.subtotal, 16150);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1454);
  assert.equal(totals.total, 17604);
});

