  // LOGO-PACK: 120000, explicit 15% discount = 18000, discounted = 102000, VAT 21% = 21420
  // WORKSHOP-DAY: 60000, gold tier 5% discount = 3000, discounted = 57000, VAT 0% = 0
  // subtotal = 275000, discount = 25750, vat = 40373, total = 289623
  assert.equal(totals.subtotal, 275000);
  assert.equal(totals.discount, 25750);
  assert.equal(totals.vat, 40373);
  assert.equal(totals.total, 289623);
});

test('invoiceTotals clamps total to zero with extreme discount and low VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'WORKSHOP-DAY',
        name: 'Workshop (day)',
        qty: 1,
        unitPrice: 100,
        vatRate: 0,
        discountPercent: 100,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100, discount = 100, vat = 0
  // total should be clamped to 0, not -0
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('normalizeId converts lowercase to uppercase', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId('c-007'), 'C-007');
});

test('normalizeId trims whitespace', () => {
  assert.equal(normalizeId('c-007 '), 'C-007');
  assert.equal(normalizeId(' c-007'), 'C-007');
  assert.equal(normalizeId(' c-007 '), 'C-007');
  assert.equal(normalizeId('	c-007	'), 'C-007');
});

test('normalizeId handles mixed case and spaces', () => {
  assert.equal(normalizeId(' c-007 '), 'C-007');
  assert.equal(normalizeId('C-007 '), 'C-007');
  assert.equal(normalizeId('c-001'), 'C-001');
});

test('normalizeId preserves already normalized IDs', () => {
  assert.equal(normalizeId('C-001'), 'C-001');
  assert.equal(normalizeId('C-007'), 'C-007');
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  // Invoice should store the normalized ID
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with spaces', () => {
  const r = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice finds customer with lowercase ID', () => {
  const r = createInvoice({
    customerId: 'c-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
});

test('createInvoice applies correct tier discount for normalized ID', () => {
  const r = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  // C-001 is gold tier (5% discount)
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice with uppercase and spaces', () => {
  const r = createInvoice({
    customerId: ' C-002 ',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
  // C-002 is standard tier (no discount)
  assert.equal(r.value.lines[0].discountPercent, undefined);
});

test('addLine normalizes customer ID from invoice', () => {
  const r1 = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r2.ok, true);
  // New line should get gold tier discount from normalized ID
  assert.equal(r2.value.lines[1].discountPercent, 5);
});

test('renderInvoiceText works with normalized customer ID', () => {
  const r = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  // Should still find customer by normalized ID
  assert.ok(text.includes('Northwind Studio'));
});

test('createInvoice defaults to NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2025-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  assert.equal(r.value.dueDate, '2025-10-21');
});

test('createInvoice accepts NET30 terms explicitly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2025-11-06');
});

test('createInvoice accepts EOM (end of month) terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  assert.equal(r.value.dueDate, '2025-10-31');
});

test('createInvoice rejects invalid terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'INVALID',
  });
  assert.equal(r.ok, false);
  assert.equal(r.error, 'TERMS_INVALID');
});

test('createInvoice NET14 calculates correctly across month boundary', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-25',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(r.value.dueDate, '2025-11-08');
});

test('createInvoice NET30 calculates correctly across month boundary', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET30',
  });
  assert.equal(r.value.dueDate, '2025-11-14');
});

test('createInvoice EOM works for early month dates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.value.dueDate, '2025-10-31');
});

test('createInvoice EOM works for late month dates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.value.dueDate, '2025-10-31');
});

test('createInvoice EOM handles February correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.value.dueDate, '2025-02-28');
});

test('createInvoice EOM handles February leap year', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(r.value.dueDate, '2024-02-29');
});

test('addLine preserves terms and dueDate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r2.value.terms, 'NET14');
  assert.equal(r2.value.dueDate, '2025-10-21');
});

test('removeLine preserves terms and dueDate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
    terms: 'EOM',
  });
  const invoice = r1.value;
  const r2 = removeLine(invoice, 'DEV-HOUR');
  assert.equal(r2.value.terms, 'EOM');
  assert.equal(r2.value.dueDate, '2025-10-31');
});

test('issueInvoice preserves terms and dueDate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  assert.equal(r2.value.terms, 'NET14');
  assert.equal(r2.value.dueDate, '2025-10-21');
});

test('createInvoice with NET14 and EOM for comparison', () => {
  const rNet14 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const rEOM = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  // NET14 gives 2025-10-21, EOM gives 2025-10-31 for same date
  assert.equal(rNet14.value.dueDate, '2025-10-21');
  assert.equal(rEOM.value.dueDate, '2025-10-31');
});

