import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, discountAmount, lineVAT } from '../src/invoices.js';
import { normalizeId } from '../src/customers.js';
import { renderInvoiceText } from '../src/render.js';

test('createInvoice succeeds with valid input', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2025-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[0].qty, 10);
  assert.equal(r.value.lines[0].unitPrice, 9500);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].name, 'Logo package');
  assert.equal(r.value.lines[1].qty, 1);
  assert.equal(r.value.lines[1].unitPrice, 120000);
  assert.equal(r.value.lines[1].vatRate, 21);
});

test('createInvoice reports unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '07-10-2025',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects invalid date like 2025-02-30', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects undefined lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects qty that is not an integer', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects qty of 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects negative qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 10 }];
  const originalLines = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines,
  });
  assert.equal(JSON.stringify(lines), originalLines);
});

test('createInvoice with varying VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 9);
  assert.equal(r.value.lines[1].vatRate, 0);
});

test('lineTotal multiplies qty by unitPrice', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 95000);
});

test('lineTotal with qty of 1', () => {
  const line = {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 120000);
});

test('invoiceTotals with single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // 10 * 9500 = 95000, C-001 is gold tier (5% discount = 4750)
  // Discounted = 90250, VAT 21% = 18953
  // Total = 95000 - 4750 + 18953 = 109203
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18953);
  assert.equal(totals.total, 109203);
});

test('invoiceTotals with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // 10 * 9500 + 1 * 120000 + 5 * 980 = 95000 + 120000 + 4900 = 219900
  // C-001 is gold tier, all lines get 5% discount
  // DEV-HOUR: 90250 * 21% = 18953
  // LOGO-PACK: 114000 * 21% = 23940
  // ICON-SET: 4655 * 21% = 978 (rounded)
  // discount = 10995, vat = 43871, total = 252776
  assert.equal(totals.subtotal, 219900);
  assert.equal(totals.discount, 10995);
  assert.equal(totals.vat, 43871);
  assert.equal(totals.total, 252776);
});

test('invoiceTotals with varying quantities', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'PRINT-A3', qty: 50 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // 100 * 37 + 50 * 249 = 3700 + 12450 = 16150
  // C-002 is standard tier, no discount
  // PRINT-A4: 3700 * 9% = 333
  // PRINT-A3: 12450 * 9% = 1121 (rounded)
  // VAT = 1454, Total = 17604
  assert.equal(totals.subtotal, 16150);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1454);
  assert.equal(totals.total, 17604);
});

test('addLine adds a new line to the invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[1].qty, 1);
  assert.equal(r2.value.lines[1].name, 'Logo package');
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 15);
});

test('addLine validates qty', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 0 });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'UNKNOWN-SKU', qty: 1 });
  assert.deepEqual(r2, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = {
