import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, discountAmount, lineVAT, applyVoucher } from '../src/invoices.js';
import { normalizeId } from '../src/customers.js';
import { renderInvoiceText } from '../src/render.js';
import { recordPayment } from '../src/payments.js';

test('createInvoice succeeds with valid input', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
