test('voucher reduces balance due in payments', () => {
  const { recordPayment } = require('../src/payments.js');
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  const vouched = r2.value;
  const issued = issueInvoice(vouched, []).value;
  const totals = invoiceTotals(issued);
  const r3 = recordPayment(issued, { amount: totals.total, date: '2025-10-08' });
